import{_ as a,o as n,c as i,ai as l}from"./chunks/framework.Ba-VnP44.js";const k=JSON.parse('{"title":"MCP / Tools · 工具与外部能力","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/01-foundation/mcp-tools.md","filePath":"ai/productivity/dev-spec/01-foundation/mcp-tools.md"}'),e={name:"ai/productivity/dev-spec/01-foundation/mcp-tools.md"};function p(t,s,r,h,d,c){return n(),i("div",null,[...s[0]||(s[0]=[l(`<h1 id="mcp-tools-·-工具与外部能力" tabindex="-1">MCP / Tools · 工具与外部能力 <a class="header-anchor" href="#mcp-tools-·-工具与外部能力" aria-label="Permalink to “MCP / Tools · 工具与外部能力”">​</a></h1><blockquote><p>第一层 · 能力底座。解决「AI 如何安全地连接仓库外的能力」——数据库、浏览器、外部 API、设计工具等，通过 MCP 或工具接入，但接入前要过必要性和边界检查。</p></blockquote><h2 id="解决什么问题" tabindex="-1">解决什么问题 <a class="header-anchor" href="#解决什么问题" aria-label="Permalink to “解决什么问题”">​</a></h2><ul><li>为了「看起来专业」接一堆用不上的工具，增加维护成本。</li><li>工具权限过大，AI 能读生产数据、能执行不可逆操作。</li><li>工具不可用时整个流程卡死，没有降级方案。</li><li>说不清某个工具到底给 AI 开放了什么能力。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to “核心内容”">​</a></h2><h3 id="mcp-解决什么" tabindex="-1">MCP 解决什么 <a class="header-anchor" href="#mcp-解决什么" aria-label="Permalink to “MCP 解决什么”">​</a></h3><p>MCP（Model Context Protocol）让 AI 连接<strong>仓库外的能力或数据</strong>：数据库、文件系统、浏览器、第三方 API、设计工具等。它补齐的是「AI 靠读代码拿不到的信息」和「AI 光靠写代码做不了的动作」。</p><p>不是所有能力都要 MCP。能用文件、命令、脚本解决的，优先用更简单的方式。</p><h3 id="接入前三问" tabindex="-1">接入前三问 <a class="header-anchor" href="#接入前三问" aria-label="Permalink to “接入前三问”">​</a></h3><table tabindex="0"><thead><tr><th>检查</th><th>要回答什么</th></tr></thead><tbody><tr><td>必要性</td><td>这个能力是不是仓库内拿不到、又确实完成任务必须要的？</td></tr><tr><td>边界</td><td>它开放了什么权限？只读还是可写？能碰到生产环境吗？</td></tr><tr><td>降级</td><td>它不可用时怎么办？有没有替代检查或手动方案？</td></tr></tbody></table><p>三条有一条答不上来，先不接。</p><h3 id="权限最小化" tabindex="-1">权限最小化 <a class="header-anchor" href="#权限最小化" aria-label="Permalink to “权限最小化”">​</a></h3><ul><li>能只读就不要可写。</li><li>能连测试库就不要连生产库。</li><li>能限定目录就不要开放整个文件系统。</li><li>涉及删除、写入、发送的动作，接入时就明确「需要人确认」。</li></ul><h3 id="记录能力清单" tabindex="-1">记录能力清单 <a class="header-anchor" href="#记录能力清单" aria-label="Permalink to “记录能力清单”">​</a></h3><p>接了哪些工具、各自开放什么、谁配置、怎么降级，记在项目的工具说明里。避免「某次对话接过，后来没人知道」。</p><h2 id="接入评估模板" tabindex="-1">接入评估模板 <a class="header-anchor" href="#接入评估模板" aria-label="Permalink to “接入评估模板”">​</a></h2><div class="language-markdown line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># &lt;工具/MCP 名&gt; 接入评估</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 必要性</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 解决什么问题：</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 为什么仓库内方式不够：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 边界</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 开放的能力：</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 权限级别：只读 / 可写</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 访问范围：&lt;库 / 目录 / 环境&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 是否触及生产：&lt;是 / 否&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 降级</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不可用时怎么办：</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 替代检查或手动方案：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 确认</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 由谁配置：</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 哪些动作需要人确认：</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>评估是否要接入某个工具</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我需要评估是否接入下面这个工具/MCP，请帮我做接入评估，本轮只输出评估，不做配置。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>工具名：&lt;名称&gt;</span></span>
<span class="line"><span>想解决的场景：&lt;要完成什么&gt;</span></span>
<span class="line"><span>当前卡点：&lt;为什么现在做不了&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按三问评估：</span></span>
<span class="line"><span>1. 必要性：这个能力是不是仓库内拿不到、又确实完成场景必须要的？有没有更简单的替代？</span></span>
<span class="line"><span>2. 边界：它开放什么权限？只读还是可写？能碰到生产环境或敏感数据吗？</span></span>
<span class="line"><span>3. 降级：它不可用时怎么办？有没有替代检查或手动方案？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>然后给出：权限最小化建议、哪些动作必须人确认、是否建议接入（建议 / 暂缓 / 不建议）及理由。</span></span>
<span class="line"><span>三问有答不上来的，直接标「待确认」，不要替我假设。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div></details><details><summary><strong>梳理已有工具的能力边界</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请梳理当前项目已接入的 AI 工具/MCP，输出一份能力边界清单。本轮只读分析，不修改配置。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对每个工具列出：</span></span>
<span class="line"><span>1. 开放了什么能力。</span></span>
<span class="line"><span>2. 权限级别（只读 / 可写）和访问范围。</span></span>
<span class="line"><span>3. 是否触及生产环境或敏感数据。</span></span>
<span class="line"><span>4. 哪些动作需要人确认。</span></span>
<span class="line"><span>5. 不可用的降级方案。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最后标出风险项：权限过大、触及生产、无降级方案的工具。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 每个工具都回答了必要性、边界、降级三问。</li><li>[ ] 权限最小化：只读优先、不碰生产、范围受限。</li><li>[ ] 删除、写入、发送等动作明确需要人确认。</li><li>[ ] 工具不可用时能降级，不会整体卡死。</li><li>[ ] 能力清单已记录，团队/后续会话能查到。</li></ul><p>工具是手段，不是目的。接之前先问「没有它到底行不行」。</p>`,23)])])}const o=a(e,[["render",p]]);export{k as __pageData,o as default};
